package com.example;

import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;

/**
 * Boots a HeadlessApplication that runs the procedural Pixmap renderer.
 */
public class Main {

    public static void main(String[] args) {
        if (args.length < 2) {
            System.err.println("Usage: Main <input-script> <output-png>");
            System.exit(2);
        }

        String inputPath = args[0];
        String outputPath = args[1];

        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        // Headless runs at a sensible but not infinite FPS; create() does the work.
        config.renderInterval = 1f / 30f;
        config.updatesPerSecond = 30;

        PixmapRenderer listener = new PixmapRenderer(inputPath, outputPath);
        HeadlessApplication app = new HeadlessApplication(listener, config);

        // Block this thread until the listener calls Gdx.app.exit().
        // The listener renders the summary and requests exit from render().
        while (app.getApplicationListener() != null) {
            try {
                Thread.sleep(50);
            } catch (InterruptedException ie) {
                Thread.currentThread().interrupt();
                break;
            }
        }

        // The HeadlessApplication's exit sets listener to null; ensure clean shutdown.
        try {
            app.exit();
        } catch (Throwable ignored) {
        }
    }
}
